#include <vector>
#include <algorithm>

class Solution {
    bool canMake(const std::vector<int>& bloomDay, int m, int k, int day) {
        int bouquets = 0, flowers = 0;
        for (int b : bloomDay) {
            if (b <= day) {
                flowers++;
                if (flowers == k) {
                    bouquets++;
                    flowers = 0;
                }
            } else {
                flowers = 0;
            }
        }
        return bouquets >= m;
    }
public:
    int minDays(std::vector<int>& bloomDay, int m, int k) {
        long long totalNeeded = (long long)m * k;
        if (totalNeeded > (long long)bloomDay.size()) return -1;
        int low = 1, high = 1e9, ans = -1;
        for (int b : bloomDay) {
            low = std::min(low, b);
            high = std::max(high, b);
        }
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canMake(bloomDay, m, k, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    private boolean canMake(int[] bloomDay, int m, int k, int day) {
        int bouquets = 0, flowers = 0;
        for (int b : bloomDay) {
            if (b <= day) {
                flowers++;
                if (flowers == k) {
                    bouquets++;
                    flowers = 0;
                }
            } else {
                flowers = 0;
            }
        }
        return bouquets >= m;
    }
    public int minDays(int[] bloomDay, int m, int k) {
        long totalNeeded = (long) m * k;
        if (totalNeeded > bloomDay.length) return -1;
        int low = Integer.MAX_VALUE, high = Integer.MIN_VALUE;
        for (int b : bloomDay) {
            low = Math.min(low, b);
            high = Math.max(high, b);
        }
        int ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canMake(bloomDay, m, k, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

var minDays = function(bloomDay, m, k) {
    if (m * k > bloomDay.length) return -1;
    function canMake(day) {
        let bouquets = 0, flowers = 0;
        for (const b of bloomDay) {
            if (b <= day) {
                flowers++;
                if (flowers === k) {
                    bouquets++;
                    flowers = 0;
                }
            } else {
                flowers = 0;
            }
        }
        return bouquets >= m;
    }
    let low = Math.min(...bloomDay);
    let high = Math.max(...bloomDay);
    let ans = -1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (canMake(mid)) {
            ans = mid;
